// Validate filenames/types, classify the corpus, and decide what to submit.
//
// IMPORTANT: file BYTES are never sent over HTTP. The Phase 3A ingestion API is
// path-based (source_path relative to data/raw), so the PDF never leaves disk.
// We only forward a relative path plus metadata.
//
// Idempotency is owned by the BACKEND: identical SHA-256 + identical metadata
// returns the original IDs with status 'duplicate' and no re-embedding
// (Phase 3A guide). The static-data cache below is a bandwidth optimisation
// only - wiping it is always safe.

const ctx = $('Set: Run Context').first().json;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const MAX_BYTES = 20 * 1024 * 1024;           // Phase 3A / 3B1 hard limit
const NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;
const ALLOWED_EXT = ['pdf', 'png', 'jpg', 'jpeg'];
const dataRoot = String(ctx.data_root).replace(/\/+$/, '');

// Map a data/raw subdirectory to the document_type accepted by the API.
function classify(relPath) {
  if (relPath.startsWith('pids/'))      return { type: 'pid',      isPid: true  };
  if (relPath.startsWith('sops/'))      return { type: 'sop',      isPid: false };
  if (relPath.startsWith('incidents/')) return { type: 'incident', isPid: false };
  if (relPath.startsWith('manuals/'))   return { type: 'manual',   isPid: false };
  return { type: null, isPid: false };
}

// Phase 3B1 only accepts paths beneath data/raw/pids/source/.
function relPathIsPidSource(rel) { return rel.startsWith('pids/source/'); }

const out = [];

for (const item of $input.all()) {
  const bin = (item.binary || {}).data || {};
  const fileName = String(bin.fileName || '');
  // The Read/Write Files node reports the containing directory in binary metadata.
  // If it is absent we must NOT guess a path - a wrong source_path would make the
  // API ingest the wrong file. Skip loudly instead.
  const absPath = bin.directory ? `${String(bin.directory).replace(/\/+$/, '')}/${fileName}` : '';
  const ext = String(bin.fileExtension || fileName.split('.').pop() || '').toLowerCase();
  const size = Number(bin.fileSize ? String(bin.fileSize).replace(/[^0-9]/g, '') : 0);

  const base = { run_id: ctx.run_id, file_name: fileName, abs_path: absPath, size_bytes: size };
  const reject = (reason) => out.push({ json: { ...base, decision: 'skip', reason } });

  if (!absPath)                            { reject('directory_metadata_missing'); continue; }
  if (!absPath.startsWith(dataRoot + '/')) { reject('path_outside_data_root'); continue; }
  if (!NAME_RE.test(fileName))             { reject('filename_not_allowlisted'); continue; }
  if (!ALLOWED_EXT.includes(ext))          { reject(`extension_not_allowed:${ext}`); continue; }
  if (size > MAX_BYTES)                    { reject('exceeds_20MiB_api_limit'); continue; }

  const relPath = absPath.slice(dataRoot.length + 1);
  const { type, isPid } = classify(relPath);
  if (!type) { reject('unmapped_subdirectory'); continue; }
  // Phase 3A text ingestion accepts PDF only; Phase 3B1 P&ID accepts PDF/PNG/JPG/JPEG.
  if (!isPid && ext !== 'pdf') { reject('text_corpus_requires_pdf'); continue; }
  if (isPid && !relPathIsPidSource(relPath)) { reject('pid_must_live_under_pids_source'); continue; }

  const cacheKey = `${relPath}|${size}`;
  if (store.seen[cacheKey]) { reject('already_submitted_this_instance'); continue; }

  // For P&IDs the source_path is relative to data/raw/pids/source/ (Phase 3B1),
  // for text documents it is relative to data/raw (Phase 3A). Different bases.
  const pidSourcePath = relPath.replace(/^pids\/source\//, '');

  out.push({
    json: {
      ...base,
      decision: 'submit',
      cache_key: cacheKey,
      rel_path: relPath,
      is_pid: isPid,
      document_type: type,
      ingest_body: isPid
        ? {
            source_path: pidSourcePath,
            title: fileName.replace(/\.[^.]+$/, ''),
            revision: 'unspecified',
            synthetic: false,
            render_dpi: 300,
            preprocessing: {
              grayscale: true,
              contrast_normalization: true,
              adaptive_threshold: false,
              denoise: false,
              rotation_degrees: 0
            }
          }
        : {
            source_path: relPath,
            title: fileName.replace(/\.[^.]+$/, ''),
            document_type: type,
            revision: 'unspecified',
            facility_id: ctx.facility_id,
            synthetic: false,
            access_scope: 'internal'
          }
    }
  });
}

return out;

// Classify one file's outcome. Runs for every branch, including error outputs.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const plan = $('Loop Over Files').first().json;
const res  = $input.first().json || {};

const status = Number(res.statusCode || 0);
const body   = res.body || {};
const netErr = res.error || res.message || null;

let outcome, retryable;
if (!status && netErr)          { outcome = 'transport_error'; retryable = true;  }
else if (status === 409)        { outcome = 'conflict';        retryable = false; }
else if (status >= 500)         { outcome = 'server_error';    retryable = true;  }
else if (status >= 400)         { outcome = 'rejected';        retryable = false; }
else if (body.status === 'duplicate' || body.duplicate === true) { outcome = 'duplicate'; retryable = false; }
else if (status >= 200 && status < 300) { outcome = 'ingested'; retryable = false; }
else                            { outcome = 'unknown';         retryable = true;  }

// Only cache outcomes that will not change on a retry.
if (['ingested', 'duplicate', 'rejected', 'conflict'].includes(outcome) && plan.cache_key) {
  store.seen[plan.cache_key] = { outcome, at: new Date().toISOString() };
}

return [{
  json: {
    run_id: plan.run_id,
    file_name: plan.file_name,
    rel_path: plan.rel_path,
    is_pid: plan.is_pid === true,
    document_type: plan.document_type,
    outcome,
    retryable,
    http_status: status || null,
    document_id: body.document_id || null,
    document_version_id: body.document_version_id || null,
    sha256: body.checksum_sha256 || body.sha256 || null,
    warnings: body.warnings || [],
    api_message: typeof body.detail === 'string' ? body.detail.slice(0, 300) : null,
    transport_error: netErr ? String(netErr).slice(0, 300) : null,
    recorded_at: new Date().toISOString()
  }
}];

// Aggregate the whole run into one JSONL blob + a summary item.
const ctx = $('Set: Run Context').first().json;

const planned = $('Code: Validate And Plan').all().map((i) => i.json);
const skipped = planned.filter((p) => p.decision === 'skip');
const results = $input.all().map((i) => i.json);

const tally = (name) => results.filter((r) => r.outcome === name).length;

const summary = {
  event: 'ingest_run_summary',
  run_id: ctx.run_id,
  started_at: ctx.started_at,
  finished_at: new Date().toISOString(),
  files_seen: planned.length,
  files_skipped: skipped.length,
  files_submitted: results.length,
  ingested: tally('ingested'),
  duplicate: tally('duplicate'),
  rejected: tally('rejected'),
  conflict: tally('conflict'),
  server_error: tally('server_error'),
  transport_error: tally('transport_error'),
  skip_reasons: skipped.reduce((a, s) => { a[s.reason] = (a[s.reason] || 0) + 1; return a; }, {})
};

summary.failures = summary.rejected + summary.conflict + summary.server_error + summary.transport_error;
summary.has_failures = summary.failures > 0;

const lines = [...skipped, ...results, summary].map((r) => JSON.stringify(r)).join('\n') + '\n';
const day = new Date().toISOString().slice(0, 10);

return [{
  json: {
    ...summary,
    log_path: `${$env.WB_LOG_DIR || '/data/n8n/logs'}/ingest-${day}.jsonl`,
    failed_files: results.filter((r) => ['rejected','conflict','server_error','transport_error'].includes(r.outcome))
                         .map((r) => ({ file: r.file_name, outcome: r.outcome, status: r.http_status }))
  },
  binary: {
    data: await this.helpers.prepareBinaryData(Buffer.from(lines, 'utf8'), `ingest-${day}.jsonl`, 'application/x-ndjson')
  }
}];
